  if(type==="siteEntryModal"){const module=modal.dataset.module,d=siteModules[module],r=state.siteData[module].find((x)=>x.id===id)||{};title=`${id?"修改":"新增"}${d.title}`;fields=d.fields.map(([name,label,fieldType,required])=>{if(fieldType==="inventory")return selectField(name,label,[["","未指定"],...state.inventory.map((i)=>[i.id,`${i.name}｜${i.brand}｜${i.model}`])],r[name]||"",false);if(fieldType==="workers")return workerPickerField(r.workerIds||[]);if(fieldType.startsWith("select:")){const options=fieldType.slice(7).split("|").map((v)=>v.split(","));return selectField(name,label,options,r[name]||options[0][0],required);}return inputField(name,label,fieldType,required,r[name]||"");}).join("")+submitField(id?"儲存修改":"新增資料");}
