function closeModal(){const modal=document.querySelector("#simpleModal");modal.classList.remove("open");modal.setAttribute("aria-hidden","true");modal.dataset.id="";modal.dataset.module="";modal.dataset.workLogId="";modal.dataset.projectId="";modal.dataset.contractServiceTypeId="";modal.dataset.requestId="";}
function syncModalCustomerOptions(reset=true){const form=document.querySelector("#modalForm"),category=form.elements.customerCategory,customer=form.elements.customerId;if(!category||!customer)return;const current=reset?"":customer.value,customers=sortRows(state.customers.filter((c)=>c.category===category.value),"code","asc");customer.disabled=!category.value||!customers.length;customer.innerHTML=!category.value?'<option>請先選擇客戶分類</option>':customers.length?'<option value="">請選擇客戶</option>'+customers.map((c)=>`<option value="${esc(c.id)}">${esc(c.code)}｜${esc(c.name)}</option>`).join(""):'<option>此分類目前沒有客戶</option>';if(customers.some((c)=>c.id===current))customer.value=current;syncModalProjectOptions(reset);}
function syncModalProjectOptions(reset=false){const form=document.querySelector("#modalForm"),customer=form.elements.customerId,project=form.elements.projectId;if(!customer||!project)return;const current=reset?"":project.value,projects=state.projects.filter((p)=>p.customerId===customer.value&&p.status!=="completed");project.disabled=!customer.value;project.innerHTML='<option value="">請選擇專案</option>'+projects.map((p)=>`<option value="${p.id}">${esc(p.code)}｜${esc(p.name)}</option>`).join("");if(projects.some((p)=>p.id===current))project.value=current;}
function syncWorkLogProjectNames(){const form=document.querySelector("#modalForm"),customerId=form.elements.customerId?.value||"",list=form.querySelector("#workLogProjectNames");if(!list)return;list.innerHTML=state.projects.filter((project)=>project.customerId===customerId).map((project)=>`<option value="${esc(project.name)}">${esc(project.code)}</option>`).join("");}
function syncAttachmentOptions({resetService=false,resetProject=false}={}){const form=document.querySelector("#modalForm"),customer=form.elements.customerId,service=form.elements.contractServiceTypeId,project=form.elements.projectId;if(!customer||!service||!project)return;const customerRow=byId(state.customers,customer.value),serviceCurrent=resetService?"":service.value,projectCurrent=resetProject?"":project.value,services=customerContractServiceTypes(customerRow).filter((row)=>row.active!==false),projects=state.projects.filter((row)=>row.customerId===customer.value);service.disabled=!customer.value||!services.length;service.innerHTML=!customer.value?'<option value="">請先選擇客戶</option>':services.length?'<option value="">請選擇承攬內容</option>'+services.map((row)=>`<option value="${esc(row.id)}">${esc(row.name)}</option>`).join(""):'<option value="">此客戶尚未設定承攬內容</option>';if(services.some((row)=>row.id===serviceCurrent))service.value=serviceCurrent;project.disabled=!customer.value||!projects.length;project.innerHTML=!customer.value?'<option value="">請先選擇客戶</option>':projects.length?'<option value="">請選擇專案</option>'+sortRows(projects,"code","asc").map((row)=>`<option value="${esc(row.id)}">${esc(row.code)}｜${esc(row.name)}</option>`).join(""):'<option value="">此客戶尚未建立專案</option>';if(projects.some((row)=>row.id===projectCurrent))project.value=projectCurrent;updateAttachmentPathHint();}
function updateAttachmentPathHint(){const form=document.querySelector("#modalForm"),customer=byId(state.customers,form.elements.customerId?.value),service=byId(state.contractServiceTypes,form.elements.contractServiceTypeId?.value),project=byId(state.projects,form.elements.projectId?.value),title=document.querySelector("#attachmentContextTitle"),hint=document.querySelector("#attachmentPathHint");if(title)title.textContent=customer?`${customer.code}｜${customer.name}`:"尚未選擇客戶";if(hint)hint.textContent=customer&&service&&project?`預計路徑：${NAS_TARGET_ROOT}/${safePathPart(customer.name)}/${safePathPart(service.name)}/${safePathPart(project.name)}/${today()}/檔名`:`請依序選擇客戶、承攬內容與專案；缺少任一項都不會上傳。`;}

function applyPreviewMutation(operation,payload){const version=1,now=formatDateTime(new Date());
  if(operation==="create_customer")state.customers.unshift({id:uid(),code:`PRE-${String(state.customers.length+1).padStart(3,"0")}`,category:payload.customer_category,name:payload.name,phone:payload.phone||"",email:payload.email||"",address:payload.address||"",note:payload.note||"",contractServiceCodes:[...(payload.contract_service_codes||[])],updated:now,rowVersion:version});
  if(operation==="update_customer"){const r=byId(state.customers,payload.id);Object.assign(r,{category:payload.customer_category,name:payload.name,phone:payload.phone,email:payload.email,address:payload.address,note:payload.note,contractServiceCodes:[...(payload.contract_service_codes||[])],updated:now,rowVersion:r.rowVersion+1});}if(operation==="delete_customer")state.customers=state.customers.filter((r)=>r.id!==payload.id);
  if(operation==="create_erp_project")state.projects.unshift({id:uid(),code:`PRE${String(state.projects.length+1).padStart(3,"0")}`,customerId:payload.customer_id,name:payload.name,type:payload.project_type==="maintenance"?"維修保養":"工程施工",rawType:payload.project_type,status:payload.status,owner:payload.assigned_to||"",description:payload.description||"",rowVersion:version});
  if(operation==="update_erp_project"){const r=byId(state.projects,payload.id);Object.assign(r,{customerId:payload.customer_id,name:payload.name,type:payload.project_type==="maintenance"?"維修保養":"工程施工",rawType:payload.project_type,status:payload.status,owner:payload.assigned_to||"",description:payload.description||"",rowVersion:r.rowVersion+1});}if(operation==="delete_erp_project")state.projects=state.projects.filter((r)=>r.id!==payload.id);
  if(operation==="create_supplier")state.suppliers.unshift({id:uid(),name:payload.name,contact:payload.contact_name||"",phone:payload.phone||"",email:payload.email||"",address:payload.address||"",note:payload.note||"",rowVersion:version});if(operation==="update_supplier"){const r=byId(state.suppliers,payload.id);Object.assign(r,{name:payload.name,contact:payload.contact_name,phone:payload.phone,email:payload.email,address:payload.address,note:payload.note,rowVersion:r.rowVersion+1});}if(operation==="delete_supplier")state.suppliers=state.suppliers.filter((r)=>r.id!==payload.id);
  if(operation==="create_account")state.accounts.unshift({id:uid(),username:payload.username,displayName:payload.display_name,role:payload.role,active:true,activeLabel:"啟用",updatedAt:new Date().toISOString(),updated:now,rowVersion:version});if(operation==="update_account"){const r=byId(state.accounts,payload.id);Object.assign(r,{username:payload.username,displayName:payload.display_name,role:payload.role,active:payload.is_active,activeLabel:payload.is_active?"啟用":"停用",updatedAt:new Date().toISOString(),updated:now,rowVersion:r.rowVersion+1});}if(operation==="delete_account")state.accounts=state.accounts.filter((r)=>r.id!==payload.id);
  if(operation==="create_pickup_batch")payload.rows.forEach((x,index)=>state.pickups.unshift({id:uid(),date:x.pickup_date,customerId:x.customer_id,projectId:x.project_id,itemId:x.inventory_item_id,quantity:Number(x.quantity),account:state.currentUser?.username||"預覽",workLogId:payload.work_log_id||"",requestId:payload.request_id||"",requestRow:payload.request_id?index+1:null,rowVersion:version}));if(operation==="update_pickup"){const r=byId(state.pickups,payload.id);Object.assign(r,{date:payload.pickup_date,projectId:payload.project_id,itemId:payload.inventory_item_id,quantity:Number(payload.quantity),customerId:byId(state.projects,payload.project_id)?.customerId||r.customerId,rowVersion:r.rowVersion+1});}if(operation==="delete_pickups")state.pickups=state.pickups.filter((r)=>!payload.ids.includes(r.id));
  if(operation==="create_stock_receipt_batch")payload.rows.forEach((x)=>state.receipts.unshift({id:uid(),date:x.receipt_date,supplierId:x.supplier_id,itemId:x.inventory_item_id,quantity:Number(x.quantity),note:x.note||"",rowVersion:version}));if(operation==="update_stock_receipt"){const r=byId(state.receipts,payload.id);Object.assign(r,{date:payload.receipt_date,supplierId:payload.supplier_id,itemId:payload.inventory_item_id,quantity:Number(payload.quantity),note:payload.note||"",rowVersion:r.rowVersion+1});}if(operation==="delete_stock_receipts")state.receipts=state.receipts.filter((r)=>!payload.ids.includes(r.id));
  if(operation==="create_inventory_item_batch")payload.rows.forEach((x)=>state.inventory.unshift({id:uid(),code:`PRE-${state.inventory.length+1}`,categoryId:x.category_id,category:byId(state.categories,x.category_id)?.name||"",name:x.item_name,brand:x.brand,model:x.model||"",unit:x.unit,openingQuantity:Number(x.opening_quantity),quantity:Number(x.opening_quantity),rowVersion:version}));if(operation==="update_inventory_item"){const r=byId(state.inventory,payload.id),category=byId(state.categories,payload.category_id);Object.assign(r,{categoryId:payload.category_id,category:category?.name||r.category,name:payload.item_name,brand:payload.brand,model:payload.model,unit:payload.unit,openingQuantity:Number(payload.opening_quantity),quantity:r.quantity-r.openingQuantity+Number(payload.opening_quantity),rowVersion:r.rowVersion+1});}if(operation==="delete_inventory_item")state.inventory=state.inventory.filter((r)=>r.id!==payload.id);
  if(operation==="upsert_project_site_entry"){const list=state.siteData[payload.module],existing=list.find((r)=>r.id===payload.id),values={...payload.values};if(payload.module==="logs"){values.workerIds=[...(values.worker_user_ids||[])];delete values.worker_user_ids;}if(existing)Object.assign(existing,values,{row_version:(existing.row_version||1)+1});else list.unshift({id:uid(),projectId:payload.project_id,row_version:1,...values});}if(operation==="delete_project_site_entry"){state.siteData[payload.module]=state.siteData[payload.module].filter((r)=>r.id!==payload.id);if(payload.module==="logs")state.pickups.forEach((pickup)=>{if(pickup.workLogId===payload.id)pickup.workLogId="";});}
  if(operation==="upsert_contract_site_entry"){let site=state.sites.find((row)=>row.customerId===payload.customer_id&&row.contractServiceTypeId===payload.contract_service_type_id);if(!site){site={id:uid(),siteCode:`PRE-SITE-${state.sites.length+1}`,siteName:`${byId(state.customers,payload.customer_id)?.name||"客戶"}｜${byId(state.contractServiceTypes,payload.contract_service_type_id)?.name||"承攬內容"}`,customerId:payload.customer_id,projectId:"",contractServiceTypeId:payload.contract_service_type_id,status:"active",rowVersion:1};state.sites.unshift(site);}const list=state.siteData[payload.module],existing=list.find((row)=>row.id===payload.id),values={...payload.values,siteId:site.id,site_id:site.id,customerId:payload.customer_id,contractServiceTypeId:payload.contract_service_type_id};if(existing)Object.assign(existing,values,{row_version:(existing.row_version||1)+1});else list.unshift({id:uid(),row_version:1,...values});}
  if(operation==="delete_contract_site_entry")state.siteData[payload.module]=state.siteData[payload.module].filter((row)=>row.id!==payload.id);
  if(operation==="delete_standalone_work_log"){state.siteData.logs=state.siteData.logs.filter((row)=>row.id!==payload.id);state.pickups.forEach((pickup)=>{if(pickup.workLogId===payload.id)pickup.workLogId="";});}
  if(operation==="upsert_customer_project_work_log"){let project=payload.project_id?byId(state.projects,payload.project_id):state.projects.find((item)=>item.customerId===payload.customer_id&&valueText(item.name)===valueText(payload.project_name));if(!project){project={id:uid(),code:`PRE${String(state.projects.length+1).padStart(3,"0")}`,customerId:payload.customer_id,name:payload.project_name,type:payload.work_type==="工程施工"?"工程施工":"維修保養",rawType:payload.work_type==="工程施工"?"construction":"maintenance",status:"in_progress",owner:"",description:"由工作日誌自動建立",rowVersion:1};state.projects.unshift(project);}const existing=payload.id?byId(state.siteData.logs,payload.id):null,values={projectId:project.id,log_date:payload.log_date,title:project.name,work_type:payload.work_type,summary:payload.summary||"",workerIds:[...(payload.worker_user_ids||[])]};if(existing)Object.assign(existing,values,{row_version:(existing.row_version||1)+1});else state.siteData.logs.unshift({id:uid(),row_version:1,...values});}
  if(operation==="preview_attachment_upload")payload.rows.forEach((row)=>state.siteData.assets.unshift({...row,row_version:1}));
  if(operation==="preview_attachment_delete")state.siteData.assets=state.siteData.assets.filter((row)=>row.id!==payload.id);
  state.activities.unshift({id:uid(),entityType:"預覽操作",actionCode:operation,entityId:payload.id||payload.username||"瀏覽器暫存",source:"preview",actor:state.currentUser?.username||"預覽使用者",createdAt:new Date().toISOString(),time:now});renderAll();applyUserState();}
async function mutate(operation,payload,message){if(PREVIEW_MODE){applyPreviewMutation(operation,payload);showToast(`${message}（僅預覽暫存）`);return;}await apiRequest({operation,payload});loadedScopes.clear();await loadPageData(currentPage(),{force:true});showToast(message);}

async function nasFormRequest(body,timeout=120_000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(NAS_API_ENDPOINT,{method:"POST",headers:{Authorization:`Bearer ${accessToken}`},body,signal:controller.signal}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||"附件無法上傳至 NAS。");return result;}catch(error){if(error.name==="AbortError")throw new Error("附件上傳逾時，請縮小檔案後再試。");throw error;}finally{clearTimeout(timer);}}
async function uploadAttachmentsToNas(data,customer,contractService,project,files){const appendContext=(body)=>{body.append("customer_id",customer.id);body.append("contract_service_type_id",contractService.id);body.append("project_id",project.id);};const preflightBody=new FormData();preflightBody.append("mode","preflight");appendContext(preflightBody);preflightBody.append("file_names",JSON.stringify(files.map((file)=>file.name)));const preflight=await nasFormRequest(preflightBody,45_000),conflictActions={};for(const conflict of preflight.conflicts||[]){const choice=window.prompt(`NAS 已有同名檔案：${conflict.name}\n\n輸入 1：覆蓋原檔\n輸入 2：另存新檔（${conflict.suggested_name}）\n輸入 3：取消此檔案`,`2`);conflictActions[conflict.name]=choice==="1"?"overwrite":choice==="2"?"rename":"cancel";}const body=new FormData();body.append("mode","upload");appendContext(body);body.append("description",data.description||"");body.append("attachment_type",data.attachmentType||"photo");body.append("conflict_actions",JSON.stringify(conflictActions));files.forEach((file)=>body.append("files",file,file.name));return nasFormRequest(body);}

async function handleModalSubmit(event){event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form)),modal=document.querySelector("#simpleModal"),type=modal.dataset.type,id=modal.dataset.id;form.classList.add("busy");try{
  if(type==="customerModal")await mutate(id?"update_customer":"create_customer",{...(id?{id,row_version:byId(state.customers,id).rowVersion}:{}),customer_category:data.category,name:data.name,phone:data.phone||"",email:data.email||"",address:data.address||"",note:data.note||"",contract_service_codes:[...new FormData(form).getAll("contractServiceCodes")]},id?"客戶資料已修改":"客戶已建立");
  if(type==="projectModal")await mutate(id?"update_erp_project":"create_erp_project",{...(id?{id,row_version:byId(state.projects,id).rowVersion}:{}),name:data.name,customer_id:data.customerId,project_type:data.type,status:data.status,assigned_to:data.owner||"",description:data.description||"",estimated_cost:"",note:""},id?"專案資料已修改":"專案已建立");
  if(type==="supplierModal")await mutate(id?"update_supplier":"create_supplier",{...(id?{id,row_version:byId(state.suppliers,id).rowVersion}:{}),name:data.name,contact_name:data.contact||"",phone:data.phone||"",email:data.email||"",address:data.address||"",note:data.note||""},id?"供應商資料已修改":"供應商已建立");
  if(type==="pickupModal"){const project=byId(state.projects,data.projectId);if(project?.customerId!==data.customerId)throw new Error("所選專案不屬於該客戶，請重新選擇。");const rows=id?[]:collectTransactionBatchRows("pickup");await mutate(id?"update_pickup":"create_pickup_batch",id?{id,row_version:byId(state.pickups,id).rowVersion,pickup_date:data.date,project_id:data.projectId,inventory_item_id:data.itemId,quantity:Number(data.quantity)}:{request_id:modal.dataset.requestId,rows:rows.map((r)=>({customer_id:data.customerId,pickup_date:data.date,project_id:data.projectId,inventory_item_id:r.itemId,quantity:r.quantity}))},id?"取貨紀錄已修改":`${rows.length} 筆取貨紀錄已新增`);}
  if(type==="workLogPickupModal"){const log=byId(state.siteData.logs,modal.dataset.workLogId),project=byId(state.projects,log?.projectId),rows=collectTransactionBatchRows("pickup");if(!log||!project)throw new Error("找不到工作日誌或專案，請重新整理後再試。");await mutate("create_pickup_batch",{work_log_id:log.id,request_id:modal.dataset.requestId,rows:rows.map((r)=>({customer_id:project.customerId,pickup_date:data.date,project_id:project.id,inventory_item_id:r.itemId,quantity:r.quantity}))},`${rows.length} 筆取貨已寫入工作日誌與交易管理`);}
  if(type==="receiptModal"){const rows=id?[]:collectTransactionBatchRows("receipt");await mutate(id?"update_stock_receipt":"create_stock_receipt_batch",id?{id,row_version:byId(state.receipts,id).rowVersion,receipt_date:data.date,supplier_id:data.supplierId,inventory_item_id:data.itemId,quantity:Number(data.quantity),note:data.note||""}:{rows:rows.map((r)=>({receipt_date:data.date,supplier_id:data.supplierId,inventory_item_id:r.itemId,quantity:r.quantity,note:r.note}))},id?"進貨紀錄已修改":`${rows.length} 筆進貨紀錄已新增`);}
  if(type==="itemModal")await mutate("update_inventory_item",{id,row_version:byId(state.inventory,id).rowVersion,category_id:data.category,item_name:data.name,brand:data.brand,model:data.model||"",unit:data.unit,opening_quantity:Number(data.quantity)},"品項資料已修改");
  if(type==="accountModal"){const usernameValue=data.username.trim().toLowerCase(),newPassword=data.password||"",confirmation=data.passwordConfirmation||"";if(state.accounts.some((account)=>account.id!==id&&account.username.toLowerCase()===usernameValue))throw new Error("此帳號名稱已被使用。");if(newPassword!==confirmation)throw new Error("兩次輸入的密碼不一致。");await mutate(id?"update_account":"create_account",id?{id,row_version:byId(state.accounts,id).rowVersion,username:usernameValue,display_name:data.displayName.trim(),role:data.role,is_active:data.active==="true",password:newPassword,password_confirmation:confirmation}:{username:usernameValue,display_name:data.displayName.trim(),role:data.role,password:newPassword,password_confirmation:confirmation},id?"使用者帳號資料已修改":"使用者已建立");}
  if(type==="workLogModal"){const existing=id?byId(state.siteData.logs,id):null,project=existing?byId(state.projects,existing.projectId):null,workerIds=[...new FormData(form).getAll("workerIds")],customerId=project?.customerId||data.customerId,projectName=(project?.name||data.projectName||"").trim();if(!customerId||!projectName)throw new Error("請選擇客戶並輸入專案／日誌標題。");await mutate("upsert_customer_project_work_log",{id:id||null,row_version:existing?.row_version||null,project_id:project?.id||null,customer_id:customerId,project_name:projectName,log_date:data.logDate,work_type:data.workType,summary:data.summary||"",worker_user_ids:workerIds},id?"工作日誌已修改":"工作日誌已建立並完成專案關聯");}
  if(type==="attachmentModal"){
    const customer=byId(state.customers,data.customerId),contractService=byId(state.contractServiceTypes,data.contractServiceTypeId),project=byId(state.projects,data.projectId),files=[...form.elements.files.files];
    if(!customer)throw new Error("請先選擇客戶。");
    if(!contractService||!customer.contractServiceCodes.includes(contractService.code))throw new Error("請選擇此客戶已設定的承攬內容。");
    if(!project||project.customerId!==customer.id)throw new Error("請選擇屬於目前客戶的專案，缺少專案時禁止上傳。");
    if(!PREVIEW_MODE&&!nasConnectionState.available)throw new Error("NAS 尚未通過連線檢查。");
    if(!files.length||files.length>MAX_ATTACHMENT_FILES)throw new Error(`請選擇 1～${MAX_ATTACHMENT_FILES} 個檔案。`);
    if(files.reduce((sum,file)=>sum+file.size,0)>MAX_ATTACHMENT_TOTAL_BYTES)throw new Error(`單次附件合計不可超過 ${formatBytes(MAX_ATTACHMENT_TOTAL_BYTES)}。`);
    for(const file of files){if(!file.size)throw new Error(`${file.name||"附件"} 是空白檔案，請重新選擇。`);if(file.size>MAX_ATTACHMENT_BYTES)throw new Error(`${file.name} 超過 ${formatBytes(MAX_ATTACHMENT_BYTES)}。`);if(!ATTACHMENT_ACCEPT.includes(file.type)&&file.type!=="")throw new Error(`${file.name} 的檔案格式不支援。`);}
    if(PREVIEW_MODE){const logDate=today(),site=state.sites.find((row)=>row.customerId===customer.id&&row.contractServiceTypeId===contractService.id),rows=files.map((file)=>({id:uid(),siteId:site?.id||"",site_id:site?.id||"",customerId:customer.id,contractServiceTypeId:contractService.id,contract_service_type_id:contractService.id,projectId:project.id,project_id:project.id,work_log_id:"",log_date:logDate,title:file.name,description:data.description||"",asset_type:data.attachmentType||"photo",original_name:file.name,mime_type:file.type||"application/octet-stream",file_size:file.size,nas_path:attachmentTargetPath(customer,contractService,project,file.name),upload_status:"preview",uploaded_by:state.currentUser?.username||"預覽",uploaded_at:new Date().toISOString(),sha256:"0".repeat(64)}));applyPreviewMutation("preview_attachment_upload",{rows});showToast(`${rows.length} 個附件已完成完整 NAS 路徑安全模擬；未寫入 NAS。`);}
    else{const result=await uploadAttachmentsToNas(data,customer,contractService,project,files),rows=(result.uploaded||[]).map((row)=>({...row,customerId:customer.id,contractServiceTypeId:contractService.id,projectId:project.id}));if(rows.length){try{await apiRequest({operation:"create_contract_site_attachment_batch",payload:{customer_id:customer.id,contract_service_type_id:contractService.id,project_id:project.id,rows}});loadedScopes.delete("sites");await loadPageData("sites",{force:true});}catch(error){throw new Error(`檔案已寫入 NAS，但 ERP 附件索引保存失敗：${error.message}`);}}if(result.failed?.length)showToast(`${rows.length} 個成功、${result.failed.length} 個失敗；成功檔案位於 ${result.upload_folder||NAS_TARGET_ROOT}。`,"部分上傳完成");else showToast(`${rows.length} 個附件已上傳並驗證；資料夾：${result.upload_folder||NAS_TARGET_ROOT}`);}
  }
  if(type==="siteEntryModal"){const module=modal.dataset.module,context=selectedSiteContext(),existing=state.siteData[module].find((row)=>row.id===id),values={...data};if(!context?.writable||!context.service)throw new Error("請先選擇可編輯的承攬內容。");await mutate("upsert_contract_site_entry",{module,id,customer_id:context.customer.id,contract_service_type_id:context.service.id,row_version:existing?.row_version||null,values},`${siteModules[module].title}已${id?"修改":"新增"}`);}closeModal();
}catch(error){showToast(error.message,"操作失敗");}finally{form.classList.remove("busy");}}

function updateMaterialCustomers(reset=true){updateCustomerSelect("#materialCustomerCategory","#materialCustomer",reset);updateMaterialProjects(reset);}
function updateMaterialProjects(reset=true){const customerId=document.querySelector("#materialCustomer").value,select=document.querySelector("#materialProject"),old=reset?"":select.value,projects=state.projects.filter((p)=>p.customerId===customerId);select.disabled=!customerId;select.innerHTML=customerId?'<option value="">請選擇專案</option>'+projects.map((p)=>`<option value="${esc(p.id)}">${esc(p.code)}｜${esc(p.name)}</option>`).join(""):'<option>請先選擇客戶</option>';if(old&&projects.some((p)=>p.id===old))select.value=old;document.querySelector("#materialSummary").innerHTML='<article class="empty-state"><span>≣</span><h2>請選擇專案</h2><p>系統只會顯示所選客戶實際關聯的專案。</p></article>';}
function renderMaterialSummary(){const projectId=document.querySelector("#materialProject").value,project=byId(state.projects,projectId);if(!project)return;const pickups=state.pickups.filter((p)=>p.projectId===projectId),total=pickups.reduce((s,p)=>s+p.quantity,0);document.querySelector("#materialSummary").innerHTML=`<div class="material-kpis"><div><small>用料品項</small><strong>${new Set(pickups.map((p)=>p.itemId)).size}</strong></div><div><small>領用總數</small><strong>${total}</strong></div><div><small>專案狀態</small><strong>${project.status==="completed"?"已完成":"進行中"}</strong></div></div><div class="table-card"><table><thead><tr><th>日期</th><th>品項</th><th>品牌／型號</th><th>數量</th><th>取貨帳號</th></tr></thead><tbody>${pickups.map((p)=>{const i=byId(state.inventory,p.itemId);return`<tr><td>${esc(p.date)}</td><td>${esc(i?.name)}</td><td>${esc(i?.brand)}｜${esc(i?.model)}</td><td>${esc(p.quantity)} ${esc(i?.unit)}</td><td>${esc(p.account)}</td></tr>`;}).join("")||emptyRow(5,"目前沒有用料紀錄")}</tbody></table></div>`;}
function download(name,content,type="application/json"){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function refreshSnapshot(){return loadPageData(currentPage(),{force:true});}
function showLogin(message=""){document.querySelector("#loginGate").classList.add("open");const error=document.querySelector("#loginError");error.textContent=message;error.classList.toggle("show",!!message);}
function hideLogin(){document.querySelector("#loginGate").classList.remove("open");document.querySelector("#loginError").classList.remove("show");}
function showSystemChooser(){const chooser=document.querySelector("#systemChooser"),status=document.querySelector("#systemChooserStatus");chooser.classList.add("open");chooser.setAttribute("aria-hidden","false");if(status)status.textContent=SITE_SYSTEM_TARGET_URL?"案場資料系統已可開啟。":"案場資料系統網址尚未設定；本次不會建立假網址或錯誤跳轉。";}
function hideSystemChooser(){const chooser=document.querySelector("#systemChooser");chooser.classList.remove("open");chooser.setAttribute("aria-hidden","true");}
async function chooseSystem(target,button){if(target==="sites"){if(!SITE_SYSTEM_TARGET_URL){document.querySelector("#systemChooserStatus").textContent="案場資料系統尚未建置，請先使用 ERP 系統。";showToast("尚未設定案場資料系統網址，因此未執行跳轉。","案場資料尚未開放");return;}window.location.assign(SITE_SYSTEM_TARGET_URL);return;}if(target!=="erp")return;button.disabled=true;button.querySelector("small").textContent="正在載入 Dashboard…";try{hideSystemChooser();await switchPage("dashboard");}catch(error){showSystemChooser();showToast(error.message,"ERP 首頁載入失敗");}finally{button.disabled=false;button.querySelector("small").textContent="進入目前的專案與庫存 Dashboard";}}
function logout(){accessToken="";sessionStorage.removeItem(SESSION_KEY);loadedScopes.clear();scopeRequests.clear();lastSnapshot=null;nasConnectionState={checked:false,checking:false,available:false,message:"登入後檢查 NAS 連線"};state=emptyState();hideSystemChooser();renderAll();applyUserState();showLogin();}
function setSearch(name,value,render){tableState[name].search=value.trim().toLocaleLowerCase("zh-Hant");tableState[name].page=1;render();}
function setSort(name,value,render){const[key,direction]=value.split(":");tableState[name].sortKey=key;tableState[name].direction=direction;tableState[name].page=1;render();}
function rerenderTable(name){if(["pickup","receipt"].includes(name))renderTransactions();else if(name==="inventory")renderInventory();else if(name==="user")renderUsers();else if(name==="log")renderSystemLogs();else if(name==="worklog")renderWorkLogs();else renderMasterData();}

document.addEventListener("click",async(event)=>{
  const nav=event.target.closest("[data-page].nav-item");if(nav)await switchPage(nav.dataset.page);
  const go=event.target.closest("[data-goto]");if(go)await switchPage(go.dataset.goto);
  const open=event.target.closest("[data-open]");if(open)openModal(open.dataset.open);
  if(event.target.closest("[data-close]"))closeModal();
  const dismiss=event.target.closest("[data-dismiss]");if(dismiss)dismiss.closest(".notice").remove();
  const addTransaction=event.target.closest("[data-add-transaction-row]");if(addTransaction)addTransactionBatchRow(addTransaction.dataset.addTransactionRow);
  const removeTransaction=event.target.closest("[data-remove-batch-row]");if(removeTransaction){const rows=document.querySelectorAll("#transactionBatchRows [data-batch-row]");if(rows.length<=1)showToast("至少保留一筆明細。","無法刪除");else{removeTransaction.closest("[data-batch-row]").remove();updateBatchButtons();}}
  if(event.target.closest("[data-add-item-row]"))addItemBatchRow();
  const removeItem=event.target.closest("[data-remove-item-row]");if(removeItem){const rows=document.querySelectorAll("#itemBatchRows [data-item-batch-row]");if(rows.length<=1)showToast("至少保留一筆品項。","無法刪除");else{removeItem.closest("[data-item-batch-row]").remove();updateBatchButtons();}}
  const tabJump=event.target.closest("[data-tab-jump]");if(tabJump)document.querySelector(`[data-tabs=inventory] [data-tab=${tabJump.dataset.tabJump}]`)?.click();
  const pageMove=event.target.closest("[data-page-move]");if(pageMove){const c=tableState[pageMove.dataset.pageMove];c.page+=pageMove.dataset.to==="next"?1:-1;rerenderTable(pageMove.dataset.pageMove);}
  const header=event.target.closest("[data-table-sort]");if(header){const name=header.dataset.tableSort,c=tableState[name],key=header.dataset.key;c.direction=c.sortKey===key&&c.direction==="asc"?"desc":"asc";c.sortKey=key;c.page=1;rerenderTable(name);}
  const actions=[["edit-customer","customerModal"],["edit-project","projectModal"],["edit-supplier","supplierModal"],["edit-item","itemModal"],["edit-pickup","pickupModal"],["edit-receipt","receiptModal"],["edit-account","accountModal"]];
  for(const[attr,type]of actions){const el=event.target.closest(`[data-${attr}]`);if(el){const key=attr.replace(/-([a-z])/g,(_,c)=>c.toUpperCase());openModal(type,el.dataset[key]);}}
  if(event.target.closest("#editSiteCustomer")){const context=selectedSiteContext();if(context?.customer)openModal("customerModal",context.customer.id);}
  const addSite=event.target.closest("[data-add-site-entry]");if(addSite){const modal=document.querySelector("#simpleModal"),module=addSite.dataset.addSiteEntry,context=selectedSiteContext();modal.dataset.module=module;modal.dataset.contractServiceTypeId=context?.service?.id||"";openModal(module==="assets"?"attachmentModal":"siteEntryModal");}
  const editSite=event.target.closest("[data-edit-site-entry]");if(editSite){const modal=document.querySelector("#simpleModal");modal.dataset.module=editSite.dataset.editSiteEntry;openModal("siteEntryModal",editSite.dataset.id);}
  const workLogPickup=event.target.closest("[data-work-log-pickup]");if(workLogPickup)openModal("workLogPickupModal",workLogPickup.dataset.workLogPickup);
  const editWorkLog=event.target.closest("[data-edit-work-log]");if(editWorkLog)openModal("workLogModal",editWorkLog.dataset.editWorkLog);
  const workLogAttachment=event.target.closest("[data-work-log-attachment]");if(workLogAttachment){const log=byId(state.siteData.logs,workLogAttachment.dataset.workLogAttachment),modal=document.querySelector("#simpleModal");modal.dataset.workLogId=log?.id||"";openModal("attachmentModal");}
  const deleteWorkLog=event.target.closest("[data-delete-work-log]");if(deleteWorkLog&&confirm("確定刪除這筆工作日誌？既有附件會保留並解除關聯。")){const row=byId(state.siteData.logs,deleteWorkLog.dataset.deleteWorkLog);await mutate("delete_standalone_work_log",{id:row.id,row_version:row.row_version},"工作日誌已刪除");}
  const deleteSite=event.target.closest("[data-delete-site-entry]");if(deleteSite&&confirm("確定刪除這筆案場資料？")){const module=deleteSite.dataset.deleteSiteEntry,row=state.siteData[module].find((item)=>item.id===deleteSite.dataset.id),context=selectedSiteContext();if(!context?.writable)showToast("歷史未歸類資料僅供查詢。","操作已阻止");else await mutate("delete_contract_site_entry",{module,id:deleteSite.dataset.id,customer_id:context.customer.id,contract_service_type_id:context.service.id,row_version:row?.row_version},"案場資料已刪除");}
  const deleteAttachment=event.target.closest("[data-delete-attachment]");if(deleteAttachment&&confirm("確定從預覽清單移除此附件？")){if(!PREVIEW_MODE)return showToast("正式附件尚未開放刪除。","操作已阻止");await mutate("preview_attachment_delete",{id:deleteAttachment.dataset.deleteAttachment},"附件已從預覽清單移除");}
  const deletes=[["delete-customer","delete_customer",state.customers,"客戶"],["delete-project","delete_erp_project",state.projects,"專案"],["delete-supplier","delete_supplier",state.suppliers,"供應商"],["delete-item","delete_inventory_item",state.inventory,"品項"]];
  for(const[attr,op,list,label]of deletes){const el=event.target.closest(`[data-${attr}]`);if(el&&confirm(`確定刪除這筆${label}資料？`)){const key=attr.replace(/-([a-z])/g,(_,c)=>c.toUpperCase()),id=el.dataset[key],r=byId(list,id);await mutate(op,{id,row_version:r.rowVersion},`${label}資料已刪除`);}}
  const account=event.target.closest("[data-delete-account]");if(account&&confirm("確定刪除這位使用者？")){const r=byId(state.accounts,account.dataset.deleteAccount);await mutate("delete_account",{id:r.id,row_version:r.rowVersion},"使用者已刪除");}
  const pickup=event.target.closest("[data-delete-pickup]");if(pickup&&confirm("確定刪除這筆取貨紀錄？"))await mutate("delete_pickups",{ids:[pickup.dataset.deletePickup]},"取貨紀錄已刪除");
  const receipt=event.target.closest("[data-delete-receipt]");if(receipt&&confirm("確定刪除這筆進貨紀錄？"))await mutate("delete_stock_receipts",{ids:[receipt.dataset.deleteReceipt]},"進貨紀錄已刪除");
  const siteHeader=event.target.closest("[data-site-sort-key]");if(siteHeader){const c=siteTableState[siteHeader.dataset.siteSortKey],key=siteHeader.dataset.key;c.direction=c.sortKey===key&&c.direction==="asc"?"desc":"asc";c.sortKey=key;c.page=1;renderSiteModules();}
  const sitePage=event.target.closest("[data-site-page]");if(sitePage){const c=siteTableState[sitePage.dataset.sitePage];c.page+=sitePage.dataset.to==="next"?1:-1;renderSiteModules();}
});
document.addEventListener("change",(event)=>{const size=event.target.closest("[data-page-size]");if(size){const c=tableState[size.dataset.pageSize];c.perPage=Number(size.value);c.page=1;rerenderTable(size.dataset.pageSize);}if(event.target.closest("#modalForm")&&event.target.name==="customerCategory")syncModalCustomerOptions(true);if(event.target.closest("#modalForm")&&event.target.name==="customerId"){if(document.querySelector("#simpleModal").dataset.type==="attachmentModal")syncAttachmentOptions({resetService:true,resetProject:true});else{syncModalProjectOptions(true);syncWorkLogProjectNames();}}if(event.target.closest("#modalForm")&&event.target.name==="contractServiceTypeId")updateAttachmentPathHint();if(event.target.closest("#modalForm")&&event.target.name==="projectId"&&document.querySelector("#simpleModal").dataset.type==="attachmentModal")updateAttachmentPathHint();if(event.target.name==="files"&&event.target.closest("#modalForm")){const files=[...event.target.files],output=document.querySelector("#attachmentFileSummary");if(output)output.textContent=files.length?`已選擇 ${files.length} 個檔案，共 ${formatBytes(files.reduce((sum,file)=>sum+file.size,0))}`:"尚未選擇檔案";}const batchCategory=event.target.closest("[data-batch-category]");if(batchCategory)syncBatchItemOptions(batchCategory.closest("[data-batch-row]"));const siteSize=event.target.closest("[data-site-page-size]");if(siteSize){const c=siteTableState[siteSize.dataset.sitePageSize];c.perPage=Number(siteSize.value);c.page=1;renderSiteModules();}const siteSort=event.target.closest("[data-site-sort]");if(siteSort){const c=siteTableState[siteSort.dataset.siteSort];c.sortKey=siteSort.value;c.page=1;renderSiteModules();}});
document.addEventListener("input",(event)=>{const input=event.target.closest("[data-site-search]");if(input){const c=siteTableState[input.dataset.siteSearch];c.search=input.value.toLocaleLowerCase("zh-Hant");c.page=1;renderSiteModules();const restored=document.querySelector(`[data-site-search=${input.dataset.siteSearch}]`);restored?.focus();restored?.setSelectionRange(restored.value.length,restored.value.length);}});

document.querySelector("#loginForm").addEventListener("submit",async(event)=>{event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form)),button=form.querySelector("button");button.disabled=true;button.textContent="驗證帳號中…";try{const auth=await apiRequest({operation:"login",payload:{username:data.username,password:data.password}});accessToken=auth.session?.access_token||"";if(!accessToken)throw new Error("登入工作階段建立失敗。");sessionStorage.setItem(SESSION_KEY,accessToken);state.currentUser=auth.current_user||null;loadedScopes.clear();lastSnapshot={current_user:auth.current_user||null};renderAll();applyUserState();form.reset();hideLogin();showSystemChooser();}catch(error){if(!accessToken){sessionStorage.removeItem(SESSION_KEY);showLogin(error.message);}else showToast(error.message,"登入後流程載入失敗");}finally{button.disabled=false;button.textContent=PREVIEW_MODE?"登入安全預覽":"登入正式系統";}});
