document.querySelector("#exportBackup").addEventListener("click",async()=>{try{const result=await loadScope("backup",{force:true,silent:true});if(result?.errors?.length)throw new Error(`仍有 ${result.errors.length} 項資料無法載入，已取消匯出以避免產生不完整備份。`);if(!lastSnapshot)throw new Error("尚未取得備份資料。");const snapshot=structuredClone(lastSnapshot);delete snapshot.errors;delete snapshot.scope;snapshot.customers=(snapshot.customers||[]).map((customer)=>({...customer,customer_category:customer.customer_category||inferCustomerCategory(customer.name)}));download(`guc-erp-database-${today()}.json`,JSON.stringify(snapshot,null,2));showToast("含客戶分類的資料庫快照已下載。");}catch(error){showToast(error.message,"備份匯出失敗");}});document.querySelector("#exportInventory").addEventListener("click",()=>{const csv=['編號,種類,品名,品牌,型號,單位,庫存',...state.inventory.map((i)=>[i.code,i.category,i.name,i.brand,i.model,i.unit,i.quantity].map((v)=>`"${String(v).replaceAll('"','""')}"`).join(','))].join('\n');download(`inventory-${today()}.csv`,'\ufeff'+csv,'text/csv;charset=utf-8');showToast("庫存清單已匯出。");});document.querySelector("#exportMaterials").addEventListener("click",()=>showToast("請先選擇專案，再匯出用料清單。","提示"));
